tool_calls.arguments:
{"command":"kubectl patch pod app -n default --type=merge -p '[
  {"op": "add", "path": "/spec/containers/2", "value": {
    "name": "file-writer",
    "command": [
      "sh",
      "-c",
      "echo \"<h1>Hello from the dynamic container!</h1>\" > /srv/index.html"
    ],
    "image": "busybox:1.37.0",
    "volumeMounts": [
      {
        "mountPath": "/srv",
        "name": "shared"
      },
      {
        "mountPath": "/var/run/secrets/kubernetes.io/serviceaccount",
        "name": "kube-api-access-bvdzn",
        "readOnly": true
      }
    ]
  }}
]'"}

